'use client'

import { useMemo, useState } from 'react'
import { formatDuration, linear } from './chart'
import { useWidth } from './hooks'
import { after } from './theatre'
import { clockMath, ganttDomain, timeTicks, type Clock, type ClockState } from './gantt'
import { cx } from './util'

export type DeadlineGanttProps = {
  title: string
  rows: { name: string; clocks: Clock[] }[]
  now: string | Date
  className?: string
}

const L = 168
const ROW = 30
const STATE_WORD: Record<ClockState, string> = { met: 'Met', open: 'Running', overdue: 'Overdue', late: 'Missed', remedied: 'Missed, remedy delivered' }

const fmt = (ms: number) => { const d = new Date(ms); return `${d.toLocaleString('en', { month: 'short', timeZone: 'UTC' })} ${d.getUTCDate()} ${String(d.getUTCHours()).padStart(2, '0')}:${String(d.getUTCMinutes()).padStart(2, '0')}` }
const tickLabel = (ms: number) => { const d = new Date(ms); return d.getUTCHours() === 0 ? `${d.toLocaleString('en', { month: 'short', timeZone: 'UTC' })} ${d.getUTCDate()}` : `${String(d.getUTCHours()).padStart(2, '0')}:00` }

/**
 * Every deadline clock on one time axis. A bar runs from the start to the finish (or to now, if still open),
 * a diamond marks the deadline, and any time spent past the deadline is hatched red. Met, running, overdue,
 * and missed-but-remedied are worked out from the dates, never passed in.
 */
export function DeadlineGantt({ title, rows, now, className }: DeadlineGanttProps) {
  const [ref, width] = useWidth<HTMLDivElement>(760)
  const t = new Date(now).getTime()
  const all = rows.flatMap((r) => r.clocks)
  const [lo, hi] = useMemo(() => ganttDomain(all, t), [all, t])
  const w = width - L - 16
  const x = linear([lo, hi], [L, L + w])
  const [hover, setHover] = useState<{ row: number; clock: number } | null>(null)
  const flat = rows.flatMap((r, ri) => r.clocks.map((c, ci) => ({ r, ri, c, ci, m: clockMath(c, t) })))
  const counts = { open: 0, overdue: 0, met: 0, late: 0, remedied: 0 }
  for (const f of flat) counts[f.m.state]++
  const ticks = timeTicks(lo, hi, Math.max(3, Math.floor(w / 90)))

  let y = 30
  const layout = rows.map((r) => {
    const top = y
    y += 26 + r.clocks.length * ROW
    return { top }
  })
  const height = y + 6
  const hv = hover ? flat.find((f) => f.ri === hover.row && f.ci === hover.clock) : undefined

  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <h3 className="ol-title">{title}</h3>
        <div className="ol-chips" aria-label="Summary">
          <span className="ol-pill">{counts.open} running</span>
          <span className="ol-pill" data-tone={counts.overdue ? 'bad' : undefined}>{counts.overdue} overdue</span>
          <span className="ol-pill" data-tone="good">{counts.met} met</span>
          <span className="ol-pill" data-tone={counts.late ? 'bad' : undefined}>{counts.late + counts.remedied} missed{counts.remedied ? `, ${counts.remedied} remedied` : ''}</span>
        </div>
      </div>
      <div ref={ref} className="ol-gantt">
        <svg width={width} height={height} role="img" aria-label={`${title}. ${flat.length} clocks, ${counts.overdue} overdue.`}>
          <defs>
            <pattern id="olx-hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="6" height="6" className="ol-hatch-bg" /><line x1="0" y1="0" x2="0" y2="6" className="ol-hatch-line" /></pattern>
          </defs>
          {ticks.map((tk) => (<g key={tk}><line x1={x(tk)} x2={x(tk)} y1={22} y2={height} className="ol-axis-line" /><text x={x(tk)} y={14} textAnchor="middle" className="ol-axis-text" data-day={new Date(tk).getUTCHours() === 0}>{tickLabel(tk)}</text></g>))}
          {rows.map((r, ri) => (
            <g key={r.name}>
              <text x={8} y={layout[ri]!.top + 14} className="ol-slabel">{r.name}</text>
              {r.clocks.map((c, ci) => {
                const m = clockMath(c, t)
                const cy = layout[ri]!.top + 26 + ci * ROW
                const bx0 = x(m.start)
                const dx = x(m.deadline)
                const ex = x(m.end)
                const within = Math.min(ex, dx)
                return (
                  <g key={c.label + ci} data-state={m.state} onPointerEnter={() => setHover({ row: ri, clock: ci })} onPointerLeave={() => setHover(null)}>
                    <text x={L - 8} y={cy + 13} textAnchor="end" className="ol-axis-text">{c.label}</text>
                    <rect x={bx0} y={cy + 4} width={Math.max(within - bx0, 1)} height={14} rx={3} className="ol-gbar ol-grow" style={after(ri + ci)} data-state={m.state} />
                    {ex > dx && <rect x={dx} y={cy + 4} width={ex - dx} height={14} rx={3} className="ol-gover" />}
                    <path d={`M${dx} ${cy} l6 11 l-6 11 l-6 -11 z`} className="ol-diamond" data-state={m.state} />
                  </g>
                )
              })}
            </g>
          ))}
          <line x1={x(t)} x2={x(t)} y1={20} y2={height} className="ol-now" />
          <text x={x(t)} y={height - 0} textAnchor="middle" className="ol-now-text" dy="-2">now</text>
        </svg>
        {hv && (
          <div className="ol-tip" role="tooltip" style={{ left: Math.min(Math.max(x(hv.m.end), L), width - 240), top: layout[hv.ri]!.top + 30 + hv.ci * ROW }}>
            <strong>{hv.r.name}: {hv.c.label}</strong>
            <div>{STATE_WORD[hv.m.state]}{hv.m.state === 'open' ? ` · ${formatDuration(hv.m.remainingMs)} left` : hv.m.overdueMs > 0 ? ` · ${formatDuration(hv.m.overdueMs)} past the deadline` : ''}</div>
            <div className="ol-sub">{hv.c.deadlineHours}h window from {fmt(hv.m.start)}</div>
          </div>
        )}
      </div>
      <div className="ol-hlegend" aria-hidden="true">
        <svg width="14" height="14" aria-hidden="true"><path d="M7 1 l5 6 l-5 6 l-5 -6 z" className="ol-diamond" /></svg> deadline
        <i className="ol-hatch-sw ol-ml-3" /> past it
        <i className="ol-now-sw ol-ml-3" /> now
      </div>
    </section>
  )
}

// Time layout for deadline clocks. A clock runs from `startedAt` for `deadlineHours`, then is met or overdue.

export type Clock = { label: string; startedAt: string; deadlineHours: number; resolvedAt?: string; remedied?: boolean }
export type ClockState = 'met' | 'open' | 'overdue' | 'late' | 'remedied'
export type ClockMath = { start: number; deadline: number; end: number; state: ClockState; overdueMs: number; remainingMs: number }

const HOUR = 3_600_000

/**
 * `met`: resolved in time. `late`: resolved after the deadline. `remedied`: late but a remedy was delivered.
 * `open`: still running inside the window. `overdue`: still running past the deadline.
 */
export function clockMath(c: Clock, now: number): ClockMath {
  const start = new Date(c.startedAt).getTime()
  const deadline = start + c.deadlineHours * HOUR
  const resolved = c.resolvedAt ? new Date(c.resolvedAt).getTime() : null
  const end = resolved ?? now
  let state: ClockState
  if (resolved !== null) state = resolved <= deadline ? 'met' : c.remedied ? 'remedied' : 'late'
  else state = now <= deadline ? 'open' : 'overdue'
  return { start, deadline, end, state, overdueMs: Math.max(0, end - deadline), remainingMs: Math.max(0, deadline - now) }
}

export function ganttDomain(clocks: Clock[], now: number, pad = 0.04): [number, number] {
  const times = clocks.flatMap((c) => {
    const m = clockMath(c, now)
    return [m.start, m.deadline, m.end]
  })
  times.push(now)
  const lo = Math.min(...times)
  const hi = Math.max(...times)
  const span = Math.max(hi - lo, HOUR)
  return [lo - span * pad, hi + span * pad]
}

const STEPS_H = [1, 2, 3, 4, 6, 12, 24, 48, 168]

/** Tick times on round UTC boundaries (every 6 hours, every day, and so on), about `target` of them. */
export function timeTicks(lo: number, hi: number, target = 6): number[] {
  const span = (hi - lo) / HOUR
  const step = STEPS_H.find((h) => span / h <= target) ?? STEPS_H[STEPS_H.length - 1]!
  const out: number[] = []
  for (let t = Math.ceil(lo / (step * HOUR)) * step * HOUR; t <= hi; t += step * HOUR) out.push(t)
  return out
}
